"""Markdown data types shared by the CLI and expression evaluator."""
import json
import math
from dataclasses import dataclass, field


def number_text(value):
    if math.isnan(value):
        return 'NaN'
    if math.isinf(value):
        return '-inf' if value < 0 else 'inf'
    if value == int(value):
        return str(int(value)) if value != 0 or math.copysign(1, value) > 0 else '-0'
    return str(value)


def slugify(text):
    s = ''.join(c for c in text.lower() if c.isalnum() or c.isspace() or c == '-')
    return '-'.join(x for x in s.replace('-', ' ').split() if x)


@dataclass
class Element:
    kind: str
    data: dict = field(default_factory=dict)

    def __getitem__(self, key):
        return self.data[key]

    def get(self, key, default=None):
        return self.data.get(key, default)

    def json(self):
        d = self.data
        if self.kind == 'heading':
            return dict(type='heading', level=d['level'], text=d['text'], line=d['line'])
        if self.kind == 'code':
            return dict(type='code', language=d['language'], content=d['content'],
                        start_line=d.get('start_line', 1), end_line=d.get('end_line', 1))
        if self.kind == 'link':
            return dict(type='link', text=d['text'], url=d['url'], link_type=d['link_type'])
        if self.kind == 'list':
            return dict(type='list', ordered=d['ordered'], items=[dict(content=i['content'], checked=i['checked']) for i in d['items']])
        if self.kind == 'table':
            return dict(type='table', headers=d['headers'], rows=d['rows'])
        if self.kind == 'document':
            return dict(type='document', heading_count=d['heading_count'], word_count=d['word_count'])
        return dict(type=self.kind, **d)


def typename(value):
    if isinstance(value, Element):
        return value.kind
    if value is None:
        return 'null'
    if isinstance(value, bool):
        return 'boolean'
    if isinstance(value, (int, float)):
        return 'number'
    if isinstance(value, str):
        return 'string'
    if isinstance(value, list):
        return 'array'
    return 'object'


def jsonable(v):
    if isinstance(v, Element):
        return v.json()
    if isinstance(v, dict):
        return {k: jsonable(x) for k, x in v.items()}
    if isinstance(v, list):
        return [jsonable(x) for x in v]
    if isinstance(v, float) and not math.isfinite(v):
        return None
    return v


def dump(v, pretty=False):
    return json.dumps(jsonable(v), ensure_ascii=False, indent=2 if pretty else None,
                      separators=None if pretty else (',', ':'))


def text(v):
    if isinstance(v, Element):
        d = v.data
        if v.kind in ('heading', 'link'):
            return d['text']
        if v.kind in ('code', 'document', 'blockquote', 'paragraph'):
            return d.get('content', '')
        if v.kind == 'list':
            return '\n'.join(i['content'] for i in d['items'])
        if v.kind == 'table':
            return 'Table({}x{})'.format(len(d['headers']), len(d['rows']))
        if v.kind == 'image':
            return d.get('alt', '')
    if v is None:
        return ''
    if v is True:
        return 'true'
    if v is False:
        return 'false'
    if isinstance(v, (int, float)):
        return number_text(float(v))
    if isinstance(v, str):
        return v
    if isinstance(v, list):
        return '\n'.join(text(x) for x in v)
    if isinstance(v, dict):
        return dump(v)
    return ''


def truth(v):
    if isinstance(v, Element):
        return True
    return bool(v)


def plain(v):
    if isinstance(v, Element):
        d = v.data
        if v.kind == 'heading':
            return '#' * d['level'] + ' ' + d['text']
        if v.kind == 'code':
            return '```' + (d['language'] or '') + '\n' + d['content'] + '\n```'
        if v.kind == 'link':
            return '[' + d['text'] + '](' + d['url'] + ')'
        if v.kind == 'table':
            row = lambda xs: '| ' + ' | '.join(xs) + ' |'
            return '\n'.join([row(d['headers']), row(['---'] * len(d['headers']))] + [row(r) for r in d['rows']])
        if v.kind == 'list':
            items = []
            for i, item in enumerate(d['items']):
                lead = str(i + 1) + '. ' if d['ordered'] else '- '
                if item['checked'] is not None:
                    lead += '[x] ' if item['checked'] else '[ ] '
                items.append(lead + item['content'])
            return '\n'.join(items)
        if v.kind == 'document':
            return text(v)
    if isinstance(v, list):
        return '\n'.join(plain(x) for x in v)
    if isinstance(v, dict):
        return '\n'.join(k + ': ' + plain(x) for k, x in v.items())
    return text(v)


def tree_values(values, prefix=''):
    out = ''
    for n, v in enumerate(values):
        last = n == len(values) - 1
        edge = '└──' if last else '├──'
        continuation = prefix + ('   ' if last else '│  ')
        if isinstance(v, list):
            out += prefix + edge + '[\n'
            out += tree_values(v, continuation)
            out += continuation + ']\n'
        elif isinstance(v, dict):
            out += prefix + edge + '{\n'
            for k, x in v.items():
                out += continuation + k + ': '
                if isinstance(x, (dict, list)):
                    out += '\n' + tree_values([x], continuation + '  ')
                else:
                    out += text(x) + '\n'
            out += continuation + '}\n'
        else:
            out += prefix + edge + (plain(v) if isinstance(v, Element) and v.kind == 'heading' else text(v)) + '\n'
    return out


def output_values(values, fmt):
    if not values:
        return ''
    if fmt in ('json', 'json-pretty'):
        return dump(values[0] if len(values) == 1 else values, fmt == 'json-pretty') + '\n'
    if fmt == 'jsonl':
        return '\n'.join(dump(x) for x in values) + '\n'
    if fmt == 'tree':
        return tree_values(values) + '\n'
    if fmt == 'md':
        return '\n\n'.join(x.get('raw_md', '') if isinstance(x, Element) and x.kind == 'heading' else plain(x) for x in values) + '\n'
    return '\n'.join(plain(x) for x in values) + '\n'
EOF"}

