"""A small, self-contained Markdown reader.

The block and inline readers deliberately keep source positions and raw spans:
the outline, section exporter, and query interface use different views of them.
"""
import re
import html
from dataclasses import dataclass, field
from model import Element, slugify


@dataclass
class Line:
    text: str
    start: int


@dataclass
class Node:
    kind: str
    start: int = 0
    value: str = ''
    attrs: dict = field(default_factory=dict)
    children: list = field(default_factory=list)


def unescape(s):
    return html.unescape(re.sub(r'\\([!"#$%&\'()*+,\-./:;<=>?@\[\]\\^_`{|}~])', r'\1', s))


def norm_ref(s):
    return ' '.join(s.split()).casefold()


def char_lines(s):
    # Rust's str::lines does not include the empty final line.
    if not s:
        return []
    ls = s.split('\n')
    if ls[-1] == '':
        ls.pop()
    return [x[:-1] if x.endswith('\r') else x for x in ls]


class InlineReader:
    def __init__(self, refs=None):
        self.refs = refs or {}

    def matching(self, s, pos, left, right):
        depth = 1
        i = pos + 1
        while i < len(s):
            if s[i] == '\\':
                i += 2
                continue
            if s[i] == left:
                depth += 1
            elif s[i] == right:
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return -1

    def link_at(self, s, i):
        image = s.startswith('![', i)
        begin = i + 1 if image else i
        if begin >= len(s) or s[begin] != '[':
            return None
        end = self.matching(s, begin, '[', ']')
        if end < 0:
            return None
        label = s[begin+1:end]
        k = end + 1
        dest = None
        rawdest = None
        title = None
        if k < len(s) and s[k] == '(':
            close = self.matching(s, k, '(', ')')
            if close < 0:
                return None
            raw = s[k+1:close].strip()
            # An inline destination may be angle-bracketed, or balanced and
            # followed by an optional quoted title.
            if raw.startswith('<'):
                cut = raw.find('>')
                if cut < 0:
                    return None
                dest = raw[1:cut]
                suffix = raw[cut+1:].strip()
            else:
                m = re.match(r'(?:\\.|[^\s])*', raw)
                dest = m.group(0)
                suffix = raw[len(dest):].strip()
            if suffix:
                if len(suffix) >= 2 and ((suffix[0] == suffix[-1] and suffix[0] in '\'"') or (suffix[0] == '(' and suffix[-1] == ')')):
                    title = suffix[1:-1]
                else:
                    return None
            rawdest = raw
            k = close + 1
        else:
            ref = label
            if k < len(s) and s[k] == '[':
                close = self.matching(s, k, '[', ']')
                if close < 0:
                    return None
                ref = s[k+1:close] or label
                k = close+1
            if norm_ref(ref) in self.refs:
                dest, title = self.refs[norm_ref(ref)]
                rawdest = dest
            else:
                return None
        return Node('image' if image else 'link', i, label,
                    dict(url=unescape(dest), raw_url=unescape(rawdest), title=title),
                    self.parse(label)), k

    def parse(self, s):
        out = []
        buf = ''
        def flush():
            nonlocal buf
            if buf:
                out.append(Node('text', value=buf))
                buf = ''
        i = 0
        while i < len(s):
            c = s[i]
            if c == '\n':
                hard = buf.endswith('  ')
                buf = buf.rstrip(' ')
                flush()
                out.append(Node('hardbreak' if hard else 'softbreak'))
                i += 1
                while i < len(s) and s[i] in ' \t':
                    i += 1
                continue
            if c == '\\' and i+1 < len(s):
                if s[i+1] == '\n':
                    flush()
                    out.append(Node('hardbreak'))
                    i += 2
                    continue
                if s[i+1] in '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~':
                    flush()
                    buf = s[i+1]
                    i += 2
                    continue
            if c == '&':
                m = re.match(r'&(?:#[xX][0-9a-fA-F]+|#[0-9]+|[A-Za-z][A-Za-z0-9]+);', s[i:])
                if m and html.unescape(m.group(0)) != m.group(0):
                    flush()
                    out.append(Node('text', value=html.unescape(m.group(0))))
                    i += len(m.group(0))
                    continue
            if c == '`':
                m = re.match(r'`+', s[i:])
                marks = m.group(0)
                j = i + len(marks)
                close = -1
                while j < len(s):
                    k = s.find(marks, j)
                    if k < 0:
                        break
                    before = k > 0 and s[k-1] == '`'
                    after = k+len(marks) < len(s) and s[k+len(marks)] == '`'
                    if not before and not after:
                        close = k
                        break
                    j = k+len(marks)
                if close >= 0:
                    flush()
                    code = s[i+len(marks):close].replace('\n', ' ')
                    if code.startswith(' ') and code.endswith(' ') and code.strip(' '):
                        code = code[1:-1]
                    out.append(Node('inlinecode', value=code))
                    i = close + len(marks)
                    continue
            if c == '[' or (c == '!' and s[i:i+2] == '!['):
                result = self.link_at(s, i)
                if result:
                    flush()
                    n, i = result
                    out.append(n)
                    continue
            if c == '<':
                m = re.match(r'<([^<>\n]+)>', s[i:])
                if m:
                    inside = m.group(1)
                    if re.match(r'[A-Za-z][A-Za-z0-9+.-]{1,31}:[^\s]*$', inside) or re.match(r'[^\s@]+@[^\s@]+\.[^\s@]+$', inside):
                        flush()
                        out.append(Node('link', i, inside, dict(url=unescape(inside), raw_url=unescape(inside), title=None), [Node('text', value=unescape(inside))]))
                        i += len(m.group(0))
                        continue
                    if re.match(r'/?[A-Za-z][A-Za-z0-9-]*(?:\s[^<>]*)?/?$', inside) or inside.startswith('!--'):
                        flush()
                        out.append(Node('inlinehtml', value=m.group(0)))
                        i += len(m.group(0))
                        continue
            if c in '*_~':
                run = len(s[i:]) - len(s[i:].lstrip(c))
                use = 2 if run >= 2 else 1
                if c == '~' and use == 1:
                    use = 1
                # Underscores inside a word are literal.
                inword = c == '_' and i > 0 and s[i-1].isalnum()
                if not inword and i+use < len(s) and not s[i+use].isspace():
                    marks = c*use
                    j = i+use
                    close = -1
                    while True:
                        k = s.find(marks, j)
                        if k < 0:
                            break
                        if k > i+use and not s[k-1].isspace() and (k == 0 or s[k-1] != '\\'):
                            if c != '_' or k+use == len(s) or not s[k+use].isalnum():
                                close = k
                                break
                        j = k+use
                    if close >= 0:
                        flush()
                        typ = 'strikethrough' if c == '~' else ('strong' if use == 2 else 'emphasis')
                        out.append(Node(typ, children=self.parse(s[i+use:close])))
                        i = close+use
                        continue
                # A standalone tilde at the start of a word is a distinct text
                # event, like other unmatched punctuation delimiters.
                if c == '~' and (i == 0 or s[i-1].isspace()) and i+run < len(s) and not s[i+run].isspace():
                    flush()
                    out.append(Node('text', value=c*run))
                    i += run
                    continue
            buf += c
            i += 1
        flush()
        return out


def inline_text(nodes, code=True, breaks=' '):
    out = ''
    for n in nodes:
        if n.kind == 'text':
            out += n.value
        elif n.kind == 'inlinecode':
            if code:
                out += n.value
        elif n.kind in ('softbreak', 'hardbreak'):
            out += breaks
        elif n.children:
            out += inline_text(n.children, code, breaks)
    return out


class BlockReader:
    fence_re = re.compile(r'^( {0,3})(`{3,}|~{3,})(.*)$')
    heading_re = re.compile(r'^( {0,3})(#{1,6})(?:[ \t]+(.*)|[ \t]*)$')
    list_re = re.compile(r'^( {0,3})([*+\-]|\d{1,9}[.)])(?:([ \t]+)(.*)|[ \t]*)$')
    setext_re = re.compile(r'^ {0,3}(=+|-+)[ \t]*$')
    html_re = re.compile(r'^ {0,3}</?(?:address|article|aside|base|basefont|blockquote|body|caption|center|col|colgroup|dd|details|dialog|dir|div|dl|dt|fieldset|figcaption|figure|footer|form|frame|frameset|h[1-6]|head|header|hr|html|iframe|legend|li|link|main|menu|menuitem|nav|noframes|ol|optgroup|option|p|param|search|section|summary|table|tbody|td|tfoot|th|thead|title|tr|track|ul)(?:\s|/?>)', re.I)

    def __init__(self, source):
        self.source = source
        self.lines = []
        off = 0
        for l in source.splitlines(keepends=True):
            # Only \n is a Markdown line separator.
            pass
        for l in source.split('\n'):
            self.lines.append(Line(l[:-1] if l.endswith('\r') else l, off))
            off += len(l) + 1
        if source.endswith('\n'):
            self.lines.pop()
        self.refs = {}
        for l in self.lines:
            m = re.match(r'^ {0,3}\[([^\]]+)\]:\s*(?:<([^>]+)>|(\S+))(?:\s+[\'"(](.*)[\'")])?\s*$', l.text)
            if m:
                self.refs.setdefault(norm_ref(m.group(1)), (unescape(m.group(2) or m.group(3)), m.group(4)))
        self.inline = InlineReader(self.refs)
        self.nodes = self.parse(self.lines)

    @staticmethod
    def thematic(s):
        s = s.strip()
        return len(s) >= 3 and (re.fullmatch(r'(?:\*\s*){3,}', s) or re.fullmatch(r'(?:-\s*){3,}', s) or re.fullmatch(r'(?:_\s*){3,}', s))

    @staticmethod
    def cells(s):
        s = s.strip()
        if s.startswith('|'):
            s = s[1:]
        if s.endswith('|') and not s.endswith('\\|'):
            s = s[:-1]
        return [x.strip().replace('\\|', '|') for x in re.split(r'(?<!\\)\|', s)]

    def table_align(self, s):
        if '|' not in s:
            return None
        cells = self.cells(s)
        if not cells or any(not re.fullmatch(r':?-+:?', x) for x in cells):
            return None
        return ['center' if x.startswith(':') and x.endswith(':') else 'left' if x.startswith(':') else 'right' if x.endswith(':') else 'none' for x in cells]

    def interrupt(self, s):
        return bool(self.heading_re.match(s) or self.fence_re.match(s) or re.match(r'^ {0,3}>', s) or self.thematic(s) or self.html_re.match(s) or s.lstrip().startswith('<!--') or self.list_re.match(s))

    def parse(self, lines):
        nodes = []
        i = 0
        while i < len(lines):
            line = lines[i]
            s = line.text
            if not s.strip():
                i += 1
                continue
            # Link definitions are not displayed.
            if re.match(r'^ {0,3}\[[^\]]+\]:\s*\S+', s):
                i += 1
                continue
            f = self.fence_re.match(s)
            if f and not (f.group(2)[0] == '`' and '`' in f.group(3)):
                indent, marks, info = f.groups()
                j = i+1
                body = []
                while j < len(lines):
                    t = lines[j].text
                    if re.fullmatch(r' {0,3}'+re.escape(marks[0])+r'{'+str(len(marks))+r',}[ \t]*', t):
                        j += 1
                        break
                    remove = min(len(t)-len(t.lstrip(' ')), len(indent))
                    body.append(t[remove:])
                    j += 1
                nodes.append(Node('code', line.start+len(indent), '\n'.join(body).rstrip(), dict(language=unescape(info.strip()) or None)))
                i = j
                continue
            if s.startswith('    ') or s.startswith('\t'):
                j = i
                body = []
                while j < len(lines):
                    t = lines[j].text
                    if t.startswith('    '):
                        body.append(t[4:])
                    elif t.startswith('\t'):
                        body.append(t[1:])
                    elif not t.strip():
                        body.append('')
                    else:
                        break
                    j += 1
                nodes.append(Node('code', line.start, '\n'.join(body).rstrip(), dict(language=None)))
                i = j
                continue
            # HTML block contents are opaque to the Markdown parser.
            stripped = s.lstrip()
            endmark = None
            if stripped.startswith('<!--'):
                endmark = '-->'
            elif re.match(r'<(script|pre|style|textarea)(?:\s|>)', stripped, re.I):
                endmark = '</'+re.match(r'<(\w+)', stripped).group(1)+'>'
            elif stripped.startswith('<?'):
                endmark = '?>'
            elif stripped.startswith('<![CDATA['):
                endmark = ']]>'
            elif re.match(r'<![A-Z]', stripped):
                endmark = '>'
            if endmark or self.html_re.match(s):
                j = i
                if endmark:
                    while j < len(lines):
                        t = lines[j].text
                        j += 1
                        if endmark.lower() in t.lower():
                            break
                else:
                    while j < len(lines) and lines[j].text.strip():
                        j += 1
                nodes.append(Node('html', line.start))
                i = j
                continue
            h = self.heading_re.match(s)
            if h:
                indent, marks, val = h.groups()
                val = (val or '').rstrip()
                val = re.sub(r'(?:^|[ \t]+)#+[ \t]*$', '', val)
                val = re.sub(r'[ \t]*\{(?:#[^}]*|\.[^}]*|[A-Za-z_][^}]*)\}[ \t]*$', '', val).strip()
                nodes.append(Node('heading', line.start+len(indent), val, dict(level=len(marks)), self.inline.parse(val)))
                i += 1
                continue
            q = re.match(r'^( {0,3})>([ \t]?)(.*)$', s)
            if q:
                inner = []
                j = i
                while j < len(lines):
                    t = lines[j].text
                    m = re.match(r'^( {0,3})>([ \t]?)(.*)$', t)
                    if m:
                        off = len(m.group(1))+1+len(m.group(2))
                        inner.append(Line(m.group(3), lines[j].start+off))
                    elif t.strip() and not self.interrupt(t) and inner and inner[-1].text.strip():
                        inner.append(lines[j])
                    else:
                        break
                    j += 1
                nodes.append(Node('blockquote', line.start, children=self.parse(inner)))
                i = j
                continue
            if self.thematic(s):
                nodes.append(Node('horizontalrule', line.start))
                i += 1
                continue
            lm = self.list_re.match(s)
            if lm:
                ordered = lm.group(2)[0].isdigit()
                marker = lm.group(2)[-1]
                base_indent = len(lm.group(1))
                items = []
                j = i
                loose = False
                while j < len(lines):
                    mm = self.list_re.match(lines[j].text)
                    if not mm or len(mm.group(1)) != base_indent or mm.group(2)[0].isdigit() != ordered or mm.group(2)[-1] != marker:
                        break
                    start = lines[j].start
                    spaces = mm.group(3) or ' '
                    amount = base_indent+len(mm.group(2))+len(spaces)
                    first = mm.group(4) or ''
                    if len(spaces) > 4:
                        first = spaces[1:]+first
                        amount = base_indent+len(mm.group(2))+1
                    checked = None
                    cm = re.match(r'^\[([ xX])\](?:[ \t]+|$)(.*)$', first)
                    if cm:
                        checked = cm.group(1).lower() == 'x'
                        first = cm.group(2)
                    itemlines = [Line(first, start+amount)]
                    j += 1
                    pending_blank = []
                    while j < len(lines):
                        t = lines[j].text
                        if not t.strip():
                            pending_blank.append(Line('', lines[j].start))
                            j += 1
                            continue
                        m2 = self.list_re.match(t)
                        if m2 and len(m2.group(1)) == base_indent:
                            if pending_blank:
                                loose = True
                            break
                        nspace = len(t)-len(t.lstrip(' '))
                        if nspace >= amount or t.startswith('\t'):
                            if pending_blank:
                                loose = True
                                itemlines.extend(pending_blank)
                                pending_blank = []
                            drop = amount if nspace >= amount else 1
                            itemlines.append(Line(t[drop:], lines[j].start+drop))
                            j += 1
                        elif not pending_blank and not self.interrupt(t):
                            itemlines.append(Line(t.lstrip(), lines[j].start+nspace))
                            j += 1
                        else:
                            # Blank separators belong to the surrounding block.
                            break
                    item = Node('item', start, attrs=dict(checked=checked), children=self.parse(itemlines))
                    items.append(item)
                    if j >= len(lines):
                        break
                    m2 = self.list_re.match(lines[j].text)
                    if not m2 or len(m2.group(1)) != base_indent or m2.group(2)[0].isdigit() != ordered or m2.group(2)[-1] != marker:
                        break
                nodes.append(Node('list', line.start, attrs=dict(ordered=ordered, loose=loose), children=items))
                i = j
                continue
            # Pipe tables require a delimiter row and matching column counts.
            align = self.table_align(lines[i+1].text) if i+1 < len(lines) else None
            if align is not None and len(self.cells(s)) == len(align):
                header = [self.inline.parse(x) for x in self.cells(s)]
                rows = []
                j = i+2
                while j < len(lines) and lines[j].text.strip() and '|' in lines[j].text and not self.interrupt(lines[j].text):
                    vals = self.cells(lines[j].text)
                    vals = (vals + ['']*len(align))[:len(align)]
                    rows.append([self.inline.parse(x) for x in vals])
                    j += 1
                nodes.append(Node('table', line.start, attrs=dict(headers=header, rows=rows, alignments=align)))
                i = j
                continue
            # A paragraph can itself become a setext heading.
            j = i
            parts = []
            setext = None
            while j < len(lines):
                t = lines[j].text
                if j > i:
                    sm = self.setext_re.match(t)
                    if sm:
                        setext = 1 if sm.group(1)[0] == '=' else 2
                        j += 1
                        break
                    if not t.strip() or self.interrupt(t):
                        break
                    if re.match(r'^ {0,3}\[[^\]]+\]:', t):
                        break
                parts.append(t.lstrip(' \t'))
                j += 1
            val = '\n'.join(parts)
            if setext is not None:
                nodes.append(Node('heading', line.start+len(s)-len(s.lstrip(' ')), val, dict(level=setext), self.inline.parse(val)))
            else:
                nodes.append(Node('paragraph', line.start, val, children=self.inline.parse(val)))
            i = max(j, i+1)
        return nodes


def paragraph_inline(nodes, mode='paragraph', quote=False):
    """Produce the display text and detailed inline records of a block."""
    content = ''
    inline = []
    def render(ns, style=None, inlink=False):
        nonlocal content
        for n in ns:
            if n.kind == 'text':
                if quote:
                    continue
                content += n.value
                inline.append(dict(type=style or 'text', value=n.value))
            elif n.kind in ('emphasis', 'strong', 'strikethrough'):
                render(n.children, n.kind, inlink)
            elif n.kind in ('softbreak', 'hardbreak'):
                if mode == 'tight':
                    continue
                v = '\n' if n.kind == 'hardbreak' else ' '
                content += v
                inline.append(dict(type='text', value=v))
            elif n.kind == 'inlinecode':
                content += n.value
                inline.append(dict(type='code', value=n.value))
            elif n.kind == 'link':
                # Inline code within labels remains a separate display event.
                codes = []
                def codewalk(xs):
                    for x in xs:
                        if x.kind == 'inlinecode':
                            codes.append(x)
                        codewalk(x.children)
                codewalk(n.children)
                for x in codes:
                    content += x.value
                    inline.append(dict(type='code', value=x.value))
                label = '' if quote else inline_text(n.children, code=False, breaks='')
                url = n.attrs['raw_url']
                content += '['+label+']('+url+')'
                entry = dict(type='link', text=label, url=url, title=None)
                if mode in ('tight', 'list'):
                    entry['line_offset'] = 0
                inline.append(entry)
            elif n.kind == 'image':
                alt = inline_text(n.children, code=False, breaks='')
                url = n.attrs['raw_url']
                content = '!['+alt+']('+url+')'
                inline.append(dict(type='image', alt=alt, src=url, title=None))
    render(nodes)
    return content, inline


def heading_nodes(nodes):
    for n in nodes:
        if n.kind == 'heading':
            yield n
        if n.kind in ('blockquote', 'list', 'item'):
            yield from heading_nodes(n.children)


def links_in(nodes):
    for n in nodes:
        if n.kind == 'link':
            label = inline_text(n.children, code=False, breaks='').strip()
            url = n.attrs['url']
            typ = 'anchor' if url.startswith('#') else 'external' if url.startswith(('http://', 'https://', 'mailto:')) else 'relative'
            yield Element('link', dict(text=label, url=url, link_type=typ))
        if n.kind != 'code':
            yield from links_in(n.children)
        if n.kind == 'table':
            for row in [n.attrs['headers']]+n.attrs['rows']:
                for cell in row:
                    yield from links_in(cell)


def render_blocks(nodes, start_line=1, in_quote=False):
    result = []
    def para(s, ins):
        return dict(type='paragraph', content=s, inline=ins)
    for n in nodes:
        if n.kind == 'paragraph':
            s, ins = paragraph_inline(n.children, quote=in_quote)
            if s or ins:
                result.append(para(s, ins))
        elif n.kind == 'heading':
            # Heading events consume text, but inline code is emitted to the
            # following paragraph rather than to the heading title.
            def remove_codes(xs):
                return [Node(x.kind, x.start, x.value, x.attrs, remove_codes(x.children)) for x in xs if x.kind != 'inlinecode']
            s, ins = paragraph_inline(remove_codes(n.children), quote=in_quote)
            result.append(dict(type='heading', level=n.attrs['level'], content=s, inline=ins, anchor=slugify(s)))
        elif n.kind == 'code':
            result.append(dict(type='code', language=n.attrs['language'], content=n.value, start_line=start_line, end_line=start_line))
        elif n.kind == 'horizontalrule':
            result.append(dict(type='horizontalrule'))
        elif n.kind == 'table':
            def cell(nodes):
                nonlocal result
                kept = []
                for x in nodes:
                    if x.kind == 'image':
                        result.append(dict(type='image', alt=inline_text(x.children, code=False, breaks=''), src=x.attrs['raw_url'], title=None))
                    else:
                        kept.append(x)
                return paragraph_inline(kept)[0]
            headers = [cell(x) for x in n.attrs['headers']]
            rows = [[cell(x) for x in r] for r in n.attrs['rows']]
            result.append(dict(type='table', headers=headers, alignments=n.attrs['alignments'], rows=rows))
        elif n.kind == 'list':
            items = []
            for item in n.children:
                content = ''
                inline = []
                extra = []
                seen_para = False
                def item_nodes(ns, depth=0):
                    nonlocal content, inline, seen_para
                    for b in ns:
                        if b.kind == 'paragraph':
                            mode = 'list' if n.attrs.get('loose') else 'tight'
                            s, ins = paragraph_inline(b.children, mode, in_quote)
                            if depth:
                                for x in ins:
                                    if 'value' in x:
                                        content += '\n'+'  '*depth+x['value']
                                    elif x['type'] == 'link':
                                        content += '['+x['text']+']('+x['url']+')'
                                inline.extend(ins)
                            elif seen_para and n.attrs.get('loose'):
                                extra.append(para(s, ins))
                                inline.extend(ins)
                            else:
                                content += s
                                inline.extend(ins)
                                seen_para = True
                        elif b.kind == 'list':
                            for child in b.children:
                                item_nodes(child.children, depth+1)
                        elif b.kind == 'heading':
                            result.extend(render_blocks([b], start_line, in_quote))
                        elif b.kind == 'code':
                            extra.extend(render_blocks([b], start_line, in_quote))
                        elif b.kind == 'blockquote':
                            extra.extend(render_blocks([b], start_line, in_quote))
                item_nodes(item.children)
                it = dict(checked=item.attrs.get('checked'), content=content, inline=inline)
                if extra:
                    it['blocks'] = extra
                items.append(it)
            result.append(dict(type='list', ordered=n.attrs['ordered'], items=items))
        elif n.kind == 'blockquote':
            result.extend(render_blocks(n.children, start_line, True))
            def collect(ns):
                s = ''
                for x in ns:
                    if x.kind == 'text':
                        s += x.value
                    elif x.kind != 'code':
                        s += collect(x.children)
                return s
            q = collect(n.children)
            result.append(dict(type='blockquote', content=q, blocks=[para(q, [dict(type='text', value=q)])]))
    return result


class Document:
    def __init__(self, source):
        if not any(x.lstrip().startswith('#') for x in source.split('\n')):
            source = '# Input\n\n' + source
        self.source = source
        self.reader = BlockReader(source)
        self.headings = []
        for i, n in enumerate(heading_nodes(self.reader.nodes)):
            title = inline_text(n.children, code=False, breaks='').strip()
            line = len(char_lines(source[:n.start]))+1
            byteoff = len(source[:n.start].encode('utf-8'))
            self.headings.append(Element('heading', dict(level=n.attrs['level'], text=title, line=line, offset=byteoff, char_offset=n.start, index=i)))
        self.roots = []
        stack = []
        for h in self.headings:
            while stack and stack[-1]['level'] >= h['level']:
                stack.pop()
            h.data['children'] = []
            if stack:
                stack[-1]['children'].append(h)
            else:
                self.roots.append(h)
            stack.append(h)
        for i, h in enumerate(self.headings):
            end = len(source)
            for nxt in self.headings[i+1:]:
                if nxt['level'] <= h['level']:
                    end = nxt['char_offset']
                    break
            raw = source[h['char_offset']:end]
            h.data['raw_md'] = raw
            h.data['content'] = raw.split('\n', 1)[1].strip() if '\n' in raw else ''
        self.blocks = render_blocks(self.reader.nodes)
        self.codes = [Element('code', {k:v for k,v in b.items() if k != 'type'}) for b in self.blocks if b['type'] == 'code']
        self.links = list(links_in(self.reader.nodes))
        self.lists = [Element('list', dict(ordered=b['ordered'], items=b['items'])) for b in self.blocks if b['type'] == 'list']
        self.tables = [Element('table', dict(headers=b['headers'], rows=b['rows'], alignments=b['alignments'])) for b in self.blocks if b['type'] == 'table']
        self.images = [Element('image', {k:v for k,v in b.items() if k != 'type'}) for b in self.blocks if b['type'] == 'image']
        self.word_count = len(source.split())
        self.value = Element('document', dict(content=source, heading_count=len(self.headings), word_count=self.word_count))

    def structured(self):
        def section(h):
            start = self.source.find('\n', h['char_offset'])
            offset = len(self.source[:start+1].encode('utf-8')) if start >= 0 else 0
            body = self.source[start+1:] if start >= 0 else ''
            lines = body.splitlines(keepends=True)
            kept = []
            for line in lines:
                if line.lstrip().startswith('#'):
                    break
                kept.append(line)
            raw = ''.join(kept).strip()
            reader = BlockReader(raw)
            slug = slugify(h['text'])
            return dict(id=slug, level=h['level'], title=h['text'], slug=slug,
                        position=dict(line=h['line']+1, offset=offset),
                        content=dict(raw=raw, blocks=render_blocks(reader.nodes, h['line']+1)),
                        children=[section(x) for x in h['children']])
        def depth(h):
            return 1+max([depth(x) for x in h['children']] or [0])
        metadata = dict(source=None, headingCount=len(self.headings), maxDepth=max([depth(x) for x in self.roots] or [0]), wordCount=self.word_count)
        return dict(document=dict(metadata=metadata, sections=[section(h) for h in self.roots]))

    def tree(self):
        def recur(items, prefix):
            out = ''
            for i, h in enumerate(items):
                last = i == len(items)-1
                out += prefix+('└──' if last else '├──')+'#'*h['level']+' '+h['text']+'\n'
                out += recur(h['children'], prefix+('   ' if last else '│  '))
            return out
        return recur(self.roots, '')
