"""A small, self-contained Markdown reader.

The block and inline readers deliberately keep source positions and raw spans:
the outline, section exporter, and query interface use different views of them.
"""
import re
import html
from dataclasses import dataclass, field
from model import Element, slugify


@dataclass
class Line:
    text: str
    start: int


@dataclass
class Node:
    kind: str
    start: int = 0
    value: str = ''
    attrs: dict = field(default_factory=dict)
    children: list = field(default_factory=list)


def unescape(s):
    return html.unescape(re.sub(r'\\([!"#$%&\'()*+,\-./:;<=>?@\[\]\\^_`{|}~])', r'\1', s))


def norm_ref(s):
    return ' '.join(s.split()).casefold()


def char_lines(s):
    # Rust's str::lines does not include the empty final line.
    if not s:
        return []
    ls = s.split('\n')
    if ls[-1] == '':
        ls.pop()
    return [x[:-1] if x.endswith('\r') else x for x in ls]


class InlineReader:
    def __init__(self, refs=None):
        self.refs = refs or {}

    def matching(self, s, pos, left, right):
        depth = 1
        i = pos + 1
        while i < len(s):
            if s[i] == '\\':
                i += 2
                continue
            if s[i] == left:
                depth += 1
            elif s[i] == right:
                depth -= 1
                if depth == 0:
                    return i
            i += 1
        return -1

    def link_at(self, s, i):
        image = s.startswith('![', i)
        begin = i + 1 if image else i
        if begin >= len(s) or s[begin] != '[':
            return None
        end = self.matching(s, begin, '[', ']')
        if end < 0:
            return None
        label = s[begin+1:end]
        k = end + 1
        dest = None
        rawdest = None
        title = None
        if k < len(s) and s[k] == '(':
            close = self.matching(s, k, '(', ')')
            if close < 0:
                return None
            raw = s[k+1:close].strip()
            # An inline destination may be angle-bracketed, or balanced and
            # followed by an optional quoted title.
            if raw.startswith('<'):
                cut = raw.find('>')
                if cut < 0:
                    return None
                dest = raw[1:cut]
                suffix = raw[cut+1:].strip()
            else:
                m = re.match(r'(?:\\.|[^\s])*', raw)
                dest = m.group(0)
                suffix = raw[len(dest):].strip()
            if suffix:
                if len(suffix) >= 2 and ((suffix[0] == suffix[-1] and suffix[0] in '\'"') or (suffix[0] == '(' and suffix[-1] == ')')):
                    title = suffix[1:-1]
                else:
                    return None
            rawdest = raw
            k = close + 1
        else:
            ref = label
            if k < len(s) and s[k] == '[':
                close = self.matching(s, k, '[', ']')
                if close < 0:
                    return None
                ref = s[k+1:close] or label
                k = close+1
            if norm_ref(ref) in self.refs:
                dest, title = self.refs[norm_ref(ref)]
                rawdest = dest
            else:
                return None
        return Node('image' if image else 'link', i, label,
                    dict(url=unescape(dest), raw_url=unescape(rawdest), title=title),
                    self.parse(label)), k

    def parse(self, s):
        out = []
        buf = ''
        def flush():
            nonlocal buf
            if buf:
                out.append(Node('text', value=buf))
                buf = ''
        i = 0
        while i < len(s):
            c = s[i]
            if c == '\n':
                hard = buf.endswith('  ')
                buf = buf.rstrip(' ')
                flush()
                out.append(Node('hardbreak' if hard else 'softbreak'))
                i += 1
                while i < len(s) and s[i] in ' \t':
                    i += 1
                continue
            if c == '\\' and i+1 < len(s):
                if s[i+1] == '\n':
                    flush()
                    out.append(Node('hardbreak'))
                    i += 2
                    continue
