                    if re.match(r'/?[A-Za-z][A-Za-z0-9-]*(?:\s[^<>]*)?/?$', inside) or inside.startswith('!--'):
                        flush()
                        out.append(Node('inlinehtml', value=m.group(0)))
                        i += len(m.group(0))
                        continue
            if c in '*_~':
                run = len(s[i:]) - len(s[i:].lstrip(c))
                use = 2 if run >= 2 else 1
                if c == '~' and use == 1:
                    use = 1
                # Underscores inside a word are literal.
                inword = c == '_' and i > 0 and s[i-1].isalnum()
                if not inword and i+use < len(s) and not s[i+use].isspace():
                    marks = c*use
                    j = i+use
                    close = -1
                    while True:
                        k = s.find(marks, j)
                        if k < 0:
                            break
                        if k > i+use and not s[k-1].isspace() and (k == 0 or s[k-1] != '\\'):
                            if c != '_' or k+use == len(s) or not s[k+use].isalnum():
                                close = k
                                break
                        j = k+use
                    if close >= 0:
                        flush()
                        typ = 'strikethrough' if c == '~' else ('strong' if use == 2 else 'emphasis')
                        out.append(Node(typ, children=self.parse(s[i+use:close])))
                        i = close+use
                        continue
                # A standalone tilde at the start of a word is a distinct text
                # event, like other unmatched punctuation delimiters.
                if c == '~' and (i == 0 or s[i-1].isspace()) and i+run < len(s) and not s[i+run].isspace():
                    flush()
                    out.append(Node('text', value=c*run))
                    i += run
                    continue
            buf += c
            i += 1
        flush()
        return out


def inline_text(nodes, code=True, breaks=' '):
    out = ''
    for n in nodes:
        if n.kind == 'text':
            out += n.value
        elif n.kind == 'inlinecode':
            if code:
                out += n.value
        elif n.kind in ('softbreak', 'hardbreak'):
            out += breaks
        elif n.children:
            out += inline_text(n.children, code, breaks)
    return out


class BlockReader:
    fence_re = re.compile(r'^( {0,3})(`{3,}|~{3,})(.*)$')
    heading_re = re.compile(r'^( {0,3})(#{1,6})(?:[ \t]+(.*)|[ \t]*)$')
    list_re = re.compile(r'^( {0,3})([*+\-]|\d{1,9}[.)])(?:([ \t]+)(.*)|[ \t]*)$')
    setext_re = re.compile(r'^ {0,3}(=+|-+)[ \t]*$')
    html_re = re.compile(r'^ {0,3}</?(?:address|article|aside|base|basefont|blockquote|body|caption|center|col|colgroup|dd|details|dialog|dir|div|dl|dt|fieldset|figcaption|figure|footer|form|frame|frameset|h[1-6]|head|header|hr|html|iframe|legend|li|link|main|menu|menuitem|nav|noframes|ol|optgroup|option|p|param|search|section|summary|table|tbody|td|tfoot|th|thead|title|tr|track|ul)(?:\s|/?>)', re.I)

    def __init__(self, source):
        self.source = source
        self.lines = []
        off = 0
        for l in source.splitlines(keepends=True):
            # Only \n is a Markdown line separator.
            pass
        for l in source.split('\n'):
            self.lines.append(Line(l[:-1] if l.endswith('\r') else l, off))
            off += len(l) + 1
        if source.endswith('\n'):
            self.lines.pop()
        self.refs = {}
        for l in self.lines:
            m = re.match(r'^ {0,3}\[([^\]]+)\]:\s*(?:<([^>]+)>|(\S+))(?:\s+[\'"(](.*)[\'")])?\s*$', l.text)
            if m:
                self.refs.setdefault(norm_ref(m.group(1)), (unescape(m.group(2) or m.group(3)), m.group(4)))
        self.inline = InlineReader(self.refs)
        self.nodes = self.parse(self.lines)

    @staticmethod
    def thematic(s):
        s = s.strip()
        return len(s) >= 3 and (re.fullmatch(r'(?:\*\s*){3,}', s) or re.fullmatch(r'(?:-\s*){3,}', s) or re.fullmatch(r'(?:_\s*){3,}', s))

    @staticmethod
    def cells(s):
        s = s.strip()
