                        break
                    if not t.strip() or self.interrupt(t):
                        break
                    if re.match(r'^ {0,3}\[[^\]]+\]:', t):
                        break
                parts.append(t.lstrip(' \t'))
                j += 1
            val = '\n'.join(parts)
            if setext is not None:
                nodes.append(Node('heading', line.start+len(s)-len(s.lstrip(' ')), val, dict(level=setext), self.inline.parse(val)))
            else:
                nodes.append(Node('paragraph', line.start, val, children=self.inline.parse(val)))
            i = max(j, i+1)
        return nodes


def paragraph_inline(nodes, mode='paragraph', quote=False):
    """Produce the display text and detailed inline records of a block."""
    content = ''
    inline = []
    def render(ns, style=None, inlink=False):
        nonlocal content
        for n in ns:
            if n.kind == 'text':
                if quote:
                    continue
                content += n.value
                inline.append(dict(type=style or 'text', value=n.value))
            elif n.kind in ('emphasis', 'strong', 'strikethrough'):
                render(n.children, n.kind, inlink)
            elif n.kind in ('softbreak', 'hardbreak'):
                if mode == 'tight':
                    continue
                v = '\n' if n.kind == 'hardbreak' else ' '
                content += v
                inline.append(dict(type='text', value=v))
            elif n.kind == 'inlinecode':
                content += n.value
                inline.append(dict(type='code', value=n.value))
            elif n.kind == 'link':
                # Inline code within labels remains a separate display event.
                codes = []
                def codewalk(xs):
                    for x in xs:
                        if x.kind == 'inlinecode':
                            codes.append(x)
                        codewalk(x.children)
                codewalk(n.children)
                for x in codes:
                    content += x.value
                    inline.append(dict(type='code', value=x.value))
                label = '' if quote else inline_text(n.children, code=False, breaks='')
                url = n.attrs['raw_url']
                content += '['+label+']('+url+')'
                entry = dict(type='link', text=label, url=url, title=None)
                if mode in ('tight', 'list'):
                    entry['line_offset'] = 0
                inline.append(entry)
            elif n.kind == 'image':
                alt = inline_text(n.children, code=False, breaks='')
                url = n.attrs['raw_url']
                content = '!['+alt+']('+url+')'
                inline.append(dict(type='image', alt=alt, src=url, title=None))
    render(nodes)
    return content, inline


def heading_nodes(nodes):
    for n in nodes:
        if n.kind == 'heading':
            yield n
        if n.kind in ('blockquote', 'list', 'item'):
            yield from heading_nodes(n.children)


def links_in(nodes):
    for n in nodes:
        if n.kind == 'link':
            label = inline_text(n.children, code=False, breaks='').strip()
            url = n.attrs['url']
            typ = 'anchor' if url.startswith('#') else 'external' if url.startswith(('http://', 'https://', 'mailto:')) else 'relative'
            yield Element('link', dict(text=label, url=url, link_type=typ))
        if n.kind != 'code':
            yield from links_in(n.children)
        if n.kind == 'table':
            for row in [n.attrs['headers']]+n.attrs['rows']:
                for cell in row:
                    yield from links_in(cell)


def render_blocks(nodes, start_line=1, in_quote=False):
    result = []
    def para(s, ins):
        return dict(type='paragraph', content=s, inline=ins)
