class Document:
    def __init__(self, source):
        if not any(x.lstrip().startswith('#') for x in source.split('\n')):
            source = '# Input\n\n' + source
        self.source = source
        self.reader = BlockReader(source)
        self.headings = []
        for i, n in enumerate(heading_nodes(self.reader.nodes)):
            title = inline_text(n.children, code=False, breaks='').strip()
            line = len(char_lines(source[:n.start]))+1
            byteoff = len(source[:n.start].encode('utf-8'))
            self.headings.append(Element('heading', dict(level=n.attrs['level'], text=title, line=line, offset=byteoff, char_offset=n.start, index=i)))
        self.roots = []
        stack = []
        for h in self.headings:
            while stack and stack[-1]['level'] >= h['level']:
                stack.pop()
            h.data['children'] = []
            if stack:
                stack[-1]['children'].append(h)
            else:
                self.roots.append(h)
            stack.append(h)
        for i, h in enumerate(self.headings):
            end = len(source)
            for nxt in self.headings[i+1:]:
                if nxt['level'] <= h['level']:
                    end = nxt['char_offset']
                    break
            raw = source[h['char_offset']:end]
            h.data['raw_md'] = raw
            h.data['content'] = raw.split('\n', 1)[1].strip() if '\n' in raw else ''
        self.blocks = render_blocks(self.reader.nodes)
        self.codes = [Element('code', {k:v for k,v in b.items() if k != 'type'}) for b in self.blocks if b['type'] == 'code']
        self.links = list(links_in(self.reader.nodes))
        self.lists = [Element('list', dict(ordered=b['ordered'], items=b['items'])) for b in self.blocks if b['type'] == 'list']
        self.tables = [Element('table', dict(headers=b['headers'], rows=b['rows'], alignments=b['alignments'])) for b in self.blocks if b['type'] == 'table']
        self.images = [Element('image', {k:v for k,v in b.items() if k != 'type'}) for b in self.blocks if b['type'] == 'image']
        self.word_count = len(source.split())
        self.value = Element('document', dict(content=source, heading_count=len(self.headings), word_count=self.word_count))

    def structured(self):
        def section(h):
            start = self.source.find('\n', h['char_offset'])
            offset = len(self.source[:start+1].encode('utf-8')) if start >= 0 else 0
            body = self.source[start+1:] if start >= 0 else ''
            lines = body.splitlines(keepends=True)
            kept = []
            for line in lines:
                if line.lstrip().startswith('#'):
                    break
                kept.append(line)
            raw = ''.join(kept).strip()
            reader = BlockReader(raw)
            slug = slugify(h['text'])
            return dict(id=slug, level=h['level'], title=h['text'], slug=slug,
                        position=dict(line=h['line']+1, offset=offset),
                        content=dict(raw=raw, blocks=render_blocks(reader.nodes, h['line']+1)),
                        children=[section(x) for x in h['children']])
        def depth(h):
            return 1+max([depth(x) for x in h['children']] or [0])
        metadata = dict(source=None, headingCount=len(self.headings), maxDepth=max([depth(x) for x in self.roots] or [0]), wordCount=self.word_count)
        return dict(document=dict(metadata=metadata, sections=[section(h) for h in self.roots]))

    def tree(self):
        def recur(items, prefix):
            out = ''
            for i, h in enumerate(items):
                last = i == len(items)-1
                out += prefix+('└──' if last else '├──')+'#'*h['level']+' '+h['text']+'\n'
                out += recur(h['children'], prefix+('   ' if last else '│  '))
            return out
        return recur(self.roots, '')
