class QueryError(Exception):
    def __init__(self, message, pos=None, length=1, label='unexpected token', help_text=None):
        super().__init__(message)
        self.message = message
        self.pos = pos
        self.length = length
        self.label = label
        self.help_text = help_text

    def display(self, query):
        out = 'error: '+self.message+'\n'
        if self.pos is not None:
            out += '  --> query\n  |\n1 | '+query+'\n'+' '*(4+self.pos)+'^'*max(1,self.length)+'  '+self.label+'\n'
        if self.help_text:
            if self.pos is None:
                out += '  |\n'
            out += '  = help: '+self.help_text+'\n'
        return out+'\n'


@dataclass
class Token:
    kind: str
    value: object
    pos: int
    length: int

    def describe(self):
        return {'EOF':'end of input','ID':'identifier','NUM':'number','STR':'string'}.get(self.kind, "'"+str(self.value)+"'")


def tokenize(s):
    ts = []
    i = 0
    while i < len(s):
        if s[i].isspace():
            i += 1
            continue
        start = i
        c = s[i]
        if c in '\'"':
            quote = c
            i += 1
            val = ''
            closed = False
            while i < len(s):
                if s[i] == quote:
                    i += 1
                    closed = True
                    break
                if s[i] == '\\' and i+1 < len(s):
                    i += 1
                    esc = s[i]
                    val += {'n':'\n','r':'\r','t':'\t','b':'\b','f':'\f','\\':'\\','"':'"',"'":"'"}.get(esc, esc)
                    i += 1
                else:
                    val += s[i]
                    i += 1
            if not closed:
                raise QueryError('Unterminated string', start, len(s)-start, 'unterminated string')
            ts.append(Token('STR', val, start, i-start))
            continue
        if c.isdigit():
            m = re.match(r'\d+(?:\.\d+)?(?:[eE][+-]?\d+)?', s[i:])
            val = m.group(0)
            ts.append(Token('NUM', float(val), i, len(val)))
            i += len(val)
            continue
        if c.isalpha() or c == '_':
            m = re.match(r'[^\W\d]\w*', s[i:], re.U)
            word = m.group(0)
            ts.append(Token(word if word in ('true','false','null','and','or','not') else 'ID', word, i, len(word)))
            i += len(word)
            continue
        two = s[i:i+2]
        if two in ('>>','>=','<=','==','!=','//','&&','||'):
            ts.append(Token(two, two, i, 2))
            i += 2
            continue
        if c in '.[]{}(),:|><+-*/%!':
            ts.append(Token(c, c, i, 1))
            i += 1
            continue
        advice = "Use '==' for equality comparison" if c == '=' else None
        raise QueryError("Unexpected character '"+c+"'", i, 1, 'unexpected character', advice)
    ts.append(Token('EOF', '', len(s), 1))
    return ts


class Parser:
    def __init__(self, query):
        self.query = query
        self.ts = tokenize(query)
        self.i = 0

    def peek(self, k=None):
        t = self.ts[min(self.i, len(self.ts)-1)]
        return t.kind == k if k else t

    def take(self):
        t = self.peek()
        self.i += 1
        return t

    def want(self, kind):
        if not self.peek(kind):
            t = self.peek()
            need = 'identifier' if kind == 'ID' else "'"+kind+"'"
            raise QueryError('Expected '+need+', found '+t.describe(), t.pos, t.length)
        return self.take()

    def parse(self):
        if self.peek('EOF'):
            raise QueryError('Expected expression, found end of input')
        node = self.union()
        if not self.peek('EOF'):
            t = self.peek()
            raise QueryError('Expected end of query, found '+t.describe(), t.pos, t.length)
        return node

    def union(self):
        left = self.pipe()
        seq = [left]
        while self.peek(','):
            self.take()
            seq.append(self.pipe())
        return ('union', seq) if len(seq)>1 else left

    def pipe(self):
        left = self.binary(0)
        while self.peek('|'):
            self.take()
            left = ('pipe', left, self.binary(0))
        return left

    precedences = {'//':0,'or':1,'||':1,'and':2,'&&':2,'==':3,'!=':3,'<':4,'<=':4,'>':4,'>=':4,'>>':4,'+':5,'-':5,'*':6,'/':6,'%':6}

    def binary(self, minprec):
        left = self.unary()
        while self.peek().kind in self.precedences and self.precedences[self.peek().kind] >= minprec:
            op = self.take().kind
            prec = self.precedences[op]
            right = self.binary(prec+1)
            if op == '>>' or (op == '>' and self.is_selector(left) and self.is_selector(right)):
                left = ('hierarchy', op, left, right)
            else:
                left = ('binary', op, left, right)
        return left

    @staticmethod
    def is_selector(n):
        if n[0] == 'selector':
            return True
        return n[0] == 'hierarchy'

    def unary(self):
        if self.peek('not') or self.peek('!'):
            self.take()
            return ('unary', 'not', self.unary())
        if self.peek('-'):
            self.take()
            return ('unary', '-', self.unary())
        return self.atom()

    def atom(self):
        t = self.take()
        if t.kind == '.':
            if self.peek('ID'):
                name = self.take().value
                node = ('selector', name, [])
            elif self.peek().kind in ('EOF','|',',',')',']','}','>','>>','<','>=','<=','==','!=','//','and','or','+','-','*','/'):
                node = ('identity',)
            else:
                q = self.peek()
                raise QueryError('Expected identifier, found '+q.describe(), q.pos, q.length)
        elif t.kind in ('STR','NUM'):
            node = ('literal', t.value)
        elif t.kind in ('true','false','null'):
            node = ('literal', {'true':True,'false':False,'null':None}[t.kind])
        elif t.kind == '[':
            if self.peek(']'):
                self.take()
                node = ('array', ('union', []))
            else:
                node = ('array', self.union())
                self.want(']')
        elif t.kind == '(':
            node = self.union()
            self.want(')')
            # Grouped expressions consume, but do not apply, postfix filters.
            node = ('group', node)
        elif t.kind == '{':
            pairs = []
            while not self.peek('}'):
                key = self.take()
                if key.kind not in ('ID','STR'):
                    raise QueryError('Expected object key, found '+key.describe(), key.pos, key.length)
                self.want(':')
                expr = self.pipe()
                pairs.append((key.value, expr))
