    def filter(self):
        self.want('[')
        t = self.peek()
        if t.kind == ']':
            self.take()
            return ('all',)
        if t.kind in ('ID','STR'):
            self.take()
            fil = ('exact' if t.kind == 'STR' else 'fuzzy', t.value)
        elif t.kind in ('NUM','-',':'):
