        elif t.kind in ('true','false','null'):
            node = ('literal', {'true':True,'false':False,'null':None}[t.kind])
        elif t.kind == '[':
            if self.peek(']'):
                self.take()
                node = ('array', ('union', []))
            else:
                node = ('array', self.union())
                self.want(']')
        elif t.kind == '(':
            node = self.union()
            self.want(')')
            # Grouped expressions consume, but do not apply, postfix filters.
            node = ('group', node)
        elif t.kind == '{':
            pairs = []
            while not self.peek('}'):
                key = self.take()
                if key.kind not in ('ID','STR'):
                    raise QueryError('Expected object key, found '+key.describe(), key.pos, key.length)
                self.want(':')
                expr = self.pipe()
                pairs.append((key.value, expr))
