def levenshtein(a, b):
    row = list(range(len(b)+1))
    for i, x in enumerate(a):
        nr = [i+1]
        for j, y in enumerate(b):
            nr.append(min(nr[-1]+1,row[j+1]+1,row[j]+(x!=y)))
