def read_source(files):
    if not files or (files[0] != '-' and os.path.isdir(files[0])):
        return '# Select a file\n\nPress Enter to select a markdown file.'
    try:
        if files[0] == '-':
            data = sys.stdin.buffer.read()
            if not data:
                raise CliExit('Error reading input: Empty input provided\n', 1, True)
        else:
            with open(files[0], 'rb') as f:
                data = f.read()
        return data.decode('utf-8')
    except OSError as e:
        raise CliExit('Error reading input: I/O error: '+e.strerror+' (os error '+str(e.errno)+')\n', 1, True)
    except UnicodeDecodeError:
        raise CliExit('Error reading input: I/O error: stream did not contain valid UTF-8\n', 1, True)


def completions():
    instructions = ('Shell Completion Setup Instructions\n\nAdd the appropriate line to your shell config:\n\n'
        'Bash (~/.bashrc):\n  source <(COMPLETE=bash treemd)\n\n'
        'Zsh (~/.zshrc):\n  source <(COMPLETE=zsh treemd)\n\n'
        'Fish (~/.config/fish/config.fish):\n  COMPLETE=fish treemd | source\n\n'
        'After adding the line, restart your shell or source the config file.\n')
    sys.stdout.write(instructions)
    raise CliExit('Error setting up completions: Could not detect shell\n', 1, True)


def run(argv):
    opts, files, sub = parse_args(argv)
    if opts.get('query-help'):
        return help_text('query.txt')
    if opts.get('setup-completions'):
        completions()
    if sub is not None:
        return ''
    source = read_source(files)
    doc = Document(source)
    if 'query' in opts:
        query = opts['query']
        fmt = opts.get('query-output','plain').lower()
        fmt = {'text':'plain','markdown':'md','json-pretty':'json-pretty'}.get(fmt,fmt)
        if fmt not in ('plain','md','json','json-pretty','jsonl','tree'):
            raise CliExit('Error: Unknown output format: '+opts.get('query-output','plain')+'\n', 1, True)
        try:
            expr = Parser(query).parse()
            values = Evaluator(doc).run(expr)
            return output_values(values, fmt)
        except QueryError as e:
            raise CliExit(e.display(query),1,True)
    if opts.get('count'):
        out = 'Heading counts:\n'
        for level in range(1,7):
            count = sum(h['level']==level for h in doc.headings)
            if count:
                out += '  '+'#'*level+': '+str(count)+'\n'
        return out+'\nTotal: '+str(len(doc.headings))+'\n'
    if 'section' in opts:
        target = opts['section'].lower()
        for h in doc.headings:
            if h['text'].lower() == target:
                return h['raw_md'].strip()+'\n'
        raise CliExit("Section '"+opts['section']+"' not found\n", 1, True)
    if opts.get('tree'):
        if opts['output'] == 'json':
            return dump([dict(level=h['level'],text=h['text']) for h in doc.headings], True)+'\n'
        return doc.tree()
    if opts.get('list'):
        if opts['output'] == 'json':
            return dump(doc.structured(),True)+'\n'
        if opts['output'] == 'tree':
            raise CliExit('Use --tree for tree output\n', 1, True)
        headings = doc.headings
        if 'level' in opts:
            headings = [h for h in headings if h['level'] == opts['level']]
        if 'filter' in opts:
            headings = [h for h in headings if opts['filter'].lower() in h['text'].lower()]
        return ''.join('#'*h['level']+' '+h['text']+'\n' for h in headings)
    try:
        fd = os.open('/dev/tty',os.O_RDWR)
    except OSError:
        raise CliExit(RAW_ERROR,1,True)
    os.close(fd)
    from tui import interact
    interact(doc,files,opts)
    return ''


def main():
    try:
        out = run(sys.argv[1:])
        sys.stdout.write(out)
    except CliExit as e:
        (sys.stderr if e.err else sys.stdout).write(e.text)
        sys.exit(e.status)
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except BrokenPipeError:
            pass
        sys.exit(1)


if __name__ == '__main__':
    main()
